13	/**
14	 * Handler for the `agt init` command.
15	 *
16	 * When inside a git repo, sets up a git worktree for .agentrack/ data
17	 * (orphan branch _agentrack). When not inside a git repo, falls back
18	 * to classic Tracker.init() which creates a plain directory.
19	 */
20	export async function initAction(): Promise<void> {
21	  try {
22	    const cwd = process.cwd();
23	
24	    // Try worktree-based init (only works in git repos)
25	    try {
26	      // Check if already initialized as a worktree
27	      if (isWorktreeInitialized(cwd)) {
28	        writeStdout({
29	          result: "ALREADY_INITIALIZED",
30	          path: resolve(cwd, WORKTREE_DIR),
31	        });
32	        process.exit(0);
33	      }
34	
35	      // Perform worktree setup (checks preconditions, detects scenario, mounts)
36	      const worktreeResult = initWorktree(cwd);
37	
38	      // Run tracker.init() - will return ALREADY_INITIALIZED since worktree
39	      // already contains the initial data files (from plumbing or remote).
40	      const tracker = new Tracker(cwd);
41	      await tracker.init();
42	
43	      // Auto-commit gitignore change and initialized data (fresh scenario)
44	      if (worktreeResult.scenario === "fresh") {
45	        commitGitignoreChange(cwd);
46	        commitWorktreeData(cwd, "init agentrack data");
47	      }
48	
49	      writeStdout({
50	        result: "OK",
51	        scenario: worktreeResult.scenario,
52	        path: worktreeResult.path,
53	      });
54	      process.exit(0);
55	    } catch (worktreeErr) {
56	      // If not a git repo, fall back to classic directory-based init
57	      if (
58	        worktreeErr instanceof AgentrackError &&
59	        worktreeErr.result === "NOT_A_GIT_REPO"
60	      ) {
61	        const tracker = new Tracker();
62	        const result = await tracker.init();
63	        writeStdout(result);
64	        process.exit(0);
65	      }
66	      throw worktreeErr;
67	    }
68	  } catch (err) {
69	    if (err instanceof AgentrackError) {
70	      writeStderr({ result: err.result, message: err.message });
71	      process.exit(err.exitCode);
72	    }
73	    // Unexpected errors
74	    writeStderr({ result: "INTERNAL_ERROR", message: (err as Error).message });
75	    process.exit(1);
76	  }
77	}
